matches = re.findall(r'<span class="holdings_link__kjPQ5">(.*?)</span>', html_text)
comps = [m for m in matches if m != "Net Receivables"]

map_df = pd.read_csv("Data/Factor_Data/co_code_co_name_mapping.csv")
company_names = map_df['Company Name'].dropna().tolist()

def clean_name(name):
    # Removing common suffixes for better matching
    return re.sub(r'(?i)\b(ltd\.?|co\.?|company|shares|pref\.?|eq\.?|corporation|corp\.?|services)\b', '', name).replace('-', ' ').replace('&', ' ').strip().lower()

all_df = pd.read_csv("Data/Factor_Data/company_month_ALL_FACTOR_LABELS_FINAL_COMPACT.csv", usecols=['co_code', 'Month', 'Size_Label_Monthly', 'MOM_Label'])
top500_df = pd.read_csv("Data/Factor_Data/firm_labels_top500_may_26.csv", usecols=['co_code', 'Month', 'Size_Label', 'MOM_Label'])
top300_df = pd.read_csv("Data/Factor_Data/firm_labels_top300_may_26.csv", usecols=['co_code', 'Month', 'Size_Label', 'MOM_Label'])

print("| Company | Mapped Name | All Universe (Size, MOM) | Top 500 Universe | Top 300 Universe |")
print("|---|---|---|---|---|")

clean_comps = [clean_name(cn) for cn in company_names]

# Faster matching
for comp in comps:
    ccomp = clean_name(comp)
    # exact or substring match first
    match_idx = None
    for i, c in enumerate(clean_comps):
        if ccomp == c or ccomp in c or c in ccomp:
            match_idx = i
            break
            
    if match_idx is None:
        matches = difflib.get_close_matches(ccomp, clean_comps, n=1, cutoff=0.6)
        if matches:
            match_idx = clean_comps.index(matches[0])
            
    if match_idx is not None:
        mapped_name = company_names[match_idx]
        co_code = map_df.loc[map_df['Company Name'] == mapped_name, 'Prowess company code'].values[0]
        
        all_labels = all_df[(all_df['co_code'] == co_code)].sort_values('Month').tail(1)
        t500_labels = top500_df[(top500_df['co_code'] == co_code)].sort_values('Month').tail(1)
        t300_labels = top300_df[(top300_df['co_code'] == co_code)].sort_values('Month').tail(1)
        
        def get_fmt(df_res, sz_col):
            if len(df_res) == 0: return "-"
            sz = df_res.iloc[0][sz_col]
            mom = df_res.iloc[0]['MOM_Label']
            return f"{sz}, {mom}"
            
        a_lbl = get_fmt(all_labels, 'Size_Label_Monthly')
        t5_lbl = get_fmt(t500_labels, 'Size_Label')
        t3_lbl = get_fmt(t300_labels, 'Size_Label')
        
        print(f"| {comp} | {mapped_name} | {a_lbl} | {t5_lbl} | {t3_lbl} |")
    else:
        print(f"| {comp} | NOT FOUND | - | - | - |")
